"""Audited session moderation and participant recourse, disposable metadata only."""
import argparse,datetime,json,pathlib,subprocess,time,uuid
p=argparse.ArgumentParser();p.add_argument('--root',required=True);p.add_argument('--base',required=True);p.add_argument('--cli',required=True)
a=p.parse_args();root=pathlib.Path(a.root).resolve()
if root.parent!=pathlib.Path('/var/tmp') or not root.name.startswith('fans-admission-wp-'):raise RuntimeError('Disposable root required')
wp=root/'wordpress';worker=wp/'wp-content/plugins/faluss-platform/tests/Fans/Hof/recipe/worker.php';fixture=json.loads((root/'session.json').read_text());profiles=fixture['profiles']
actors={name:value['id'] for name,value in fixture['sessions'].items()};actors['guest']=0;checks=[]
def start(actor,action,**values):
    path=root/(str(uuid.uuid4())+'.json');path.write_text(json.dumps(dict(actor=actors[actor],action=action,**values)));path.chmod(0o600)
    return subprocess.Popen(['php',a.cli,'--allow-root','--path='+str(wp),'eval-file',str(worker),str(path),'--use-include'],stdout=subprocess.PIPE,stderr=subprocess.PIPE,text=True)
def finish(process):
    out,err=process.communicate(timeout=30)
    if process.returncode:raise RuntimeError('Private moderation worker failed: '+err[-1200:])
    return json.loads(out)
def call(actor,action,**values):return finish(start(actor,action,**values))
def data(actor,action,**values):
    result=call(actor,action,**values)
    if 'error' in result:raise AssertionError(action+': '+result['error'])
    return result['data']
def check(name,condition):
    if not condition:raise AssertionError(name)
    checks.append(name);print('PASS '+name,flush=True)
def sql(query):
    result=subprocess.run(['mariadb','--no-defaults','--socket='+str(root/'sql.sock'),'-uroot','--batch','--skip-column-names','admission_recipe','-e',query],capture_output=True,text=True)
    if result.returncode:raise RuntimeError('Private moderation SQL failed')
    return result.stdout.strip()
def parallel(requests):
    barrier=root/('barrier-'+str(uuid.uuid4()));processes=[start(actor,action,**dict(values,barrier=str(barrier),worker=i)) for i,(actor,action,values) in enumerate(requests)]
    deadline=time.monotonic()+15
    while not all(pathlib.Path(str(barrier)+'.'+str(i)+'.ready').exists() for i in range(len(processes))):
        if time.monotonic()>deadline:raise RuntimeError('Concurrent moderation workers timed out')
        time.sleep(.02)
    pathlib.Path(str(barrier)+'.go').touch();return [finish(process) for process in processes]
