check('Concurrent recourse decisions commit one case revision',sum('data' in r for r in results)==1 and sum(r.get('error')=='hof_appeal_revision_conflict' for r in results)==1)
data('waiting','session_apply',session=sid,revision=6,digest=opened['frozen_sha256']);data('member','session_admit',session=sid,revision=7,creator=profiles['waiting'],allow=False)
newcase=data('waiting','participation_appeal',session=sid,role_revision=4,explanation='Nouvelle décision, précisions fictives apportées.')
